-- Seed: career roadmaps
-- Generated by content/tools/build-roadmaps.mjs from content/roadmaps.json. Do not edit by hand.
-- Idempotent: safe to run again. Apply after the course seeds (courses are linked by public id).

BEGIN;

DO $$
DECLARE
    v_missing text;
BEGIN
    SELECT string_agg(v.code, ', ') INTO v_missing
    FROM (VALUES ('frontend_developer'), ('backend_developer'), ('fullstack_developer'), ('mobile_developer'), ('devops_engineer'), ('ml_engineer'), ('qa_engineer'), ('data_engineer'), ('data_analyst'), ('student')) v(code)
    WHERE NOT EXISTS (SELECT 1 FROM catalog.career_role cr WHERE cr.code = v.code);
    IF v_missing IS NOT NULL THEN
        RAISE EXCEPTION 'unknown career roles: %', v_missing;
    END IF;
END $$;

INSERT INTO roadmap.roadmaps (id, title, description, level, career_role_id)
SELECT v.id, v.title, v.description, v.level::public.level_enum, cr.id
FROM (VALUES
    (1, 'Frontend Developer', 'From semantic HTML and accessible CSS to typed React apps that load fast: JavaScript, TypeScript, async UI code, testing and web performance.', 'beginner', 'frontend_developer'),
    (2, 'Backend Developer', 'Pick a server language, learn SQL, then build APIs and services that stay correct under concurrency, failures and attacks.', 'beginner', 'backend_developer'),
    (3, 'Fullstack Developer', 'Ship complete features: a typed React frontend, a backend API with a database, tests, deployment and AI features.', 'beginner', 'fullstack_developer'),
    (4, 'Mobile Developer', 'Build Android and cross-platform apps: Kotlin, coroutines and Flow, React Native offline-first data, and an architecture that stays testable.', 'beginner', 'mobile_developer'),
    (5, 'DevOps Engineer', 'Automate delivery and run reliable systems: processes, containers and CI, scripting, Go tooling, cloud-native services and reliability testing.', 'intermediate', 'devops_engineer'),
    (6, 'Machine Learning Engineer', 'From Python and data to models you can trust in production: ML from scratch, evaluation, retrieval-augmented generation and AI services.', 'intermediate', 'ml_engineer'),
    (7, 'QA Engineer', 'Become the engineer who finds bugs first: a programming base, test automation, API testing, test design, and performance and reliability testing.', 'beginner', 'qa_engineer'),
    (8, 'Data Engineer', 'Move and model data reliably: Python and SQL, analytics queries, pipelines with idempotent loads, async services and the ML they feed.', 'intermediate', 'data_engineer'),
    (9, 'Data Analyst', 'Answer business questions with data: SQL first, then Python, analytics queries for product metrics, pipelines and model evaluation.', 'beginner', 'data_analyst'),
    (10, 'Programming Foundations', 'Start from zero and try every major language family before choosing a career path: the web, Python and JavaScript, C and C++, typed languages, Go and Rust, SQL and testing.', 'beginner', 'student')
) v(id, title, description, level, role)
JOIN catalog.career_role cr ON cr.code = v.role
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title, description = EXCLUDED.description, level = EXCLUDED.level,
    career_role_id = EXCLUDED.career_role_id, updated_at = now();

